/* OMC-1 encoder + decoder core: slice pipeline, rate control, bitstream.
 * Release 4.15-T5 (stream minor 10): the temporal engine of minors <= 9 was
 * REMOVED (rolling in-frame reference, source-searched motion, per-block
 * motion field, in-loop temporal filter) and REBUILT as the T5 layer:
 *   - prediction reads the previous frame's FINAL committed picture only
 *     (frame-buffer reference; nothing predicts from the current frame),
 *   - the per-slice motion vector is DERIVED from committed reconstruction
 *     history (frames t-1 vs t-2), never searched against the source, so it
 *     is identical in every re-encode generation,
 *   - the cross-slice boundary edit (XSL) is ALWAYS ON and is an exactly
 *     reversible lifting cascade; the encoder un-blends its input,
 *   - the pixel domain is biased and unclipped (OMC_PIX_BIAS) so committed
 *     reconstructions survive the trip through a raw file exactly,
 *   - the generation lock is complete: at generation >= 2 every slice locks
 *     and reproduces its input bit-for-bit (see docs/TEMPORAL_T5.md for the
 *     induction argument and the measurements).
 * See docs/BITSTREAM.md for the base format and docs/TEMPORAL_T5.md for the
 * normative T5 deltas.
 */
#include <stdio.h>
#include <malloc.h>
#include "internal.h"
#include "ddr_model.h"   /* [D-DDR] inert unless OMC_DDR=1 */

/* [A1-INNOV] innovation-scale percentile used by the [A1-MZ] model-fit floor.
 * Was env OMC_MVHP_IVP; frozen at its shipped value, the lever is gone. */
#define OMC_MVHP_IVP 96
#include <stdatomic.h>

/* Synthesis-basis sign/magnitude runs, MEASURED from omc_slice_inv() by
 * repro/gen_gm_basis.c and regenerated by the build.  Used only by the strict
 * in-gamut repair, to decide whether reducing a coefficient moves an offending
 * pixel toward the legal range or further out of it.  See section 12.22. */
/* [SHARED] measured synthesis-basis boxes: used by the legacy repair (alignment veto) AND by the constructive step (candidate supports) */
#include "gm_basis_tab.c.inc"

extern int omc_xsl;       /* defined below; read by the header parser */
extern int omc_fillrung;  /* sect.B1(v5.3.5): defined below; read by common_init */

/* ------------------------------------------------------------------ common */

typedef struct {
    omc_config_t cfg;
    int W, H, Wc, sh, nslices;
    int mid, maxv;
    int xsl_lim;                 /* boundary-blend cap, codes @10-bit (minor 9) */
    int fill_rung;
    int fill_crung;              /* sect.B5: the CHROMA levers' rung (>= fill_rung) */               /* sect.B1(v5.3.5): the fill divisor's RATE RUNG.
                                    The grain the quantiser kills has a CONTENT
                                    amplitude; the fill's amplitude is a fixed
                                    fraction of the RATE-dependent step
                                    (1 << (s-2-div)), so a divisor tuned at
                                    0.5 bpp under-paints by one octave per rate
                                    octave above it -- measured as the mid-rate
                                    flatness window (cityalley@1.0: 10/32/17 %
                                    flat Y/Cb/Cr with the v5.3 divisors, 0.4/0/0
                                    with them one octave louder).  The rung
                                    lowers the divisor by one per rate octave
                                    above the base, derived from bits_per_slice
                                    exactly as xsl_lim_for() derives the blend
                                    cap: stream-constant, generation-invariant,
                                    content-blind, identical at both ends.
                                    NORMATIVE (the decoder computes the same
                                    fill) -- carried by stream minor 14.
                                    0 below 0.3125 bits per coded sample
                                    (= 0.75 display bpp at 4:2:2), 1 below
                                    0.75, 2 at/above -- i.e. one octave per
                                    rate octave, clamped where the divisor
                                    reaches zero.  omc_fillrung==0 restores
                                    v5.3 (rung pinned 0) for A/B. */
    int32_t xsl_buf[OMC_NPLANES][8192]; /* per-column d[-1], PER CONTEXT */
    int xsl_live[OMC_NPLANES];
    int xsl_noretro;             /* prev slice refreshed this frame: protect it */
    int dbg_oldpads;             /* TEST ONLY: code pad rows as ordinary content
                                    (the pre-minor-11 behaviour).  Per CONTEXT
                                    and settable only through the API below --
                                    never from the environment: an environment
                                    lever that changes normative reconstruction
                                    is an encoder/decoder disagreement channel
                                    by construction, which is the rule this
                                    codec already states for the XSL levers. */
    size_t slice_bytes, payload_bytes;
} ctx_common_t;

typedef struct {
    int64_t bits[OMC_MAX_SHIFT + 1];             /* estimated bits (incl raw) */
    uint8_t gid[OMC_MAX_SHIFT + 1];              /* table-group id */
} band_cost_t;

/* T5 generation-lock candidate: a fully-specified signalled plan.  The list
 * is large and heap-resident (in the encoder instance) because completeness
 * is part of the exactness guarantee: on generation >= 2 input the previous
 * generation's own committed plan MUST be in the list, and a small
 * evict-on-overflow buffer could push it out on pathological content. */
typedef struct {
    int64_t tot, key;
    int pr, q, ns, k;
    uint32_t modes;
    /* dedupe key: the DERIVED plan (packed 4-bit per-band shifts, partial k,
     * partial band position).  Many (pr,q,ns) triples derive the identical
     * shift vector; verify/trial outcomes depend only on the derived plan,
     * so aliases beyond the first-enumerated are dead weight (they flood the
     * candidate list and burn verify time on flat/graphics content). */
    uint8_t sv[18];
} omc_lockcand_t;
#define OMC_LOCK_CANDS 4096
/* Strict in-gamut mode: hard cap on the repair-pass BUDGET, not on the passes
 * a slice actually runs.  The cap exists so the encoder's per-slice work stays
 * BOUNDED -- an FPGA pipeline has to budget the worst case, and an unbounded
 * search has none.  Measured convergence is in docs/TEMPORAL_T5.md 12.22.
 *
 * CORRECTION 2026-09-05 (Agent 5, measured).  This comment used to read "hard
 * cap on repair passes per slice", and that is not what 16 does.  It clamps
 * the BUDGET (gamut_strict); the fallback restart and the sect.51.5f redo each
 * hand the slice a fresh budget, so the passes actually run can exceed it.
 * MEASURED 33 passes on one slice at gamut_strict = 16 (officewal 1080p 4:2:2
 * 10-bit @0.5 bpp), and 26 at the shipped default of 12 -- both above their
 * cap.  The true static per-slice bound is in the omc_gm_redomax comment
 * below.  Harness: Agents/Agent5/harness/lat_repairbound.sh; log
 * out/repairbound.log.
 *
 * ENFORCED 2026-09-08 (V15).  The bound below is no longer only a comment: a
 * per-slice counter `gm_total` counts every repair pass and is reset by no
 * restart, fallback or redo, and each of the three fresh-budget paths refuses
 * to hand the slice a new budget once it reaches
 * (3 + omc_gm_redomax) * gamut_strict.  At the cap the slice takes the EXISTING
 * exhaustion path -- committed as it stands, counted in gm_unfixed, reported,
 * and refused by the CLI with exit 2 -- not a new fallback.  The encoder now
 * prints the worst total, the cap and the p50/p90/p99 distribution on its
 * verdict line.  A test probe (OMC_GAMUT_TOTALCAP_PROBE) lowers the cap so a
 * gate can prove it is reachable; it is encoder-only and never set in
 * production.  NOTE for anyone re-measuring: the per-slice maxima quoted above
 * came from an OMC_LAT_PROF probe that no longer exists in this tree, and the
 * GAMUT stat line prints gm_iter, which every restart resets -- so it reports a
 * per-ATTEMPT number, not the total.  Use the CAP line. */
#define OMC_GAMUT_MAXPASS 16
/* [V15 2026-09-08] The static per-slice bound on repair passes, ENFORCED from
 * v5.3.7 rather than merely documented.  The four terms that hand a slice a
 * fresh pass budget are the initial budget, the SD-revert restart, the
 * harsh-rule fallback restart, and omc_gm_redomax redos -- see the
 * omc_gm_redomax comment below, which derives them and records Agent 5's
 * adversarial verification.  Hence
 *
 *     cap = (3 + omc_gm_redomax) * gamut_strict          = 52 at the defaults
 *
 * It is written as that expression, NOT as a constant, for two reasons: an
 * integrator lowers gamut_strict on a fixed slice period (LATENCY.md), and
 * omc_gm_redomax is a lever -- if either moves the bound must move with it.
 * A FIFTH reset path exists behind OMC_GM_TRIAL (off by default); it is not in
 * this factor and is not guarded, so with that lever on the total may exceed
 * the cap.  That is stated rather than tuned. */
#define OMC_GAMUT_TOTAL_FACTOR 3   /* + omc_gm_redomax; see above */
/* The default per-slice repair budget.  It is a DEFAULT, not a request: see
 * omc_enc_create.  An integrator on a fixed slice period lowers it to whatever
 * that period holds rather than switching the mode off. */
#define OMC_GAMUT_DEFPASS 13   /* [V536] 12 -> 13: Agent 3 C19-C25, external review F3; both this and GM_PASS in tests/test_xsl.c move together */


struct omc_enc {
    ctx_common_t c;
    int32_t *sbuf[OMC_NPLANES]; /* slice coeff buffers */
    int32_t *tmp;
    int32_t *coef[OMC_NPLANES][OMC_NBANDS]; /* contiguous per-band copies */
    int32_t *qbuf[OMC_NPLANES][OMC_NBANDS]; /* quantized values */
    uint8_t *syms;   /* symbol stream */
    uint8_t *stids;  /* per-symbol table id */
    uint16_t *raws;  /* raw bits value */
    uint8_t *rawn;   /* raw bits count */
    uint8_t *paybuf; /* payload scratch: oversized attempts never touch dst */
    uint8_t *rowsig; /* per-band previous-row significance (2D context) */
    uint16_t *ref[OMC_NPLANES]; /* CURRENT frame, committed slice by slice.
        T5: this rolling buffer feeds ONLY the cross-slice boundary terms
        (previous slice of the SAME frame) and, at frame end, is copied into
        refprev.  Prediction NEVER reads it — no same-frame prediction. */
    /* T5 frame-buffer references: refprev = previous frame's FINAL committed
     * picture (the only prediction source); refprev2 = the frame before it
     * (motion derivation only).  Both are generation-invariant: they equal
     * the decoder's committed pictures exactly. */
    uint16_t *refprev[OMC_NPLANES];
    uint16_t *refprev2[OMC_NPLANES];
    uint16_t *inub[OMC_NPLANES]; /* un-blended copy of the input frame */
    /* [A1-MVTRK] temporal vector tracking (encoder-only).  The outside review's
     * "motion-compensated residual reuse": carry each slice-region's committed vector
     * forward and offer it as a candidate next frame, so estimation becomes tracking
     * instead of a fresh search over an older frame pair.  Signalled vectors are
     * unchanged, so this cannot affect the wire, A5, or generation-exactness. */
    /* [A1-MVHPTC] last frame's HALF-PEL OFFSET (each component in {-1,0,1}) for this slice and
     * region, and the frame it belongs to.  Encoder-only; the signalled vector is unchanged. */
    int last_frame;             /* last frame index encoded (-1 = none) */
    int last_frame2;            /* frame index held by refprev2 (-1 = none) */
    uint16_t *state_hash;       /* [S3-HASH] per-slice hash of the committed rows
                                   of the last encoded frame (0 before the first) */
    uint8_t *refresh_req;       /* [S3-REFRESH] per-slice pending on-demand
                                   refresh (control plane); consumed at commit */
    int64_t oob_samples;        /* committed samples outside legal range (gamut
                                   report: such samples do not survive a
                                   legal-range baseband hop; see omc_enc_oob) */
    /* ---- strict in-gamut mode (encoder-only; see docs/TEMPORAL_T5.md 12.22).
     * When on, a slice whose committed reconstruction leaves the legal range
     * is RE-CODED with a pixel-domain correction folded into its SOURCE
     * coefficients, until the reconstruction is in range or the iteration
     * budget runs out.  The correction is applied strictly BEFORE
     * quantization, so what is emitted is still an ordinary lattice point and
     * the reconstruction is still the unclamped inverse transform of it: the
     * A4 exactness argument is untouched, no bitstream syntax changes, and a
     * LOCKED slice is never repaired (it already reproduces its input). */
    /* [LEGACY-REPAIR] BEGIN struct fields of the iterative repair (gamut_strict is SHARED: it also arms the legality count) */
    int gamut_strict;           /* 0 off (default), else max repair passes */
    int cdr_input;              /* caller feeds COMMITTED pictures (CDR
                                   interchange): strict mode must stand down */
    int gm_norecon;             /* a slice was coded with recon == NULL, so the
                                   gamut report could not measure it (see
                                   omc_enc_oob: it then reports -1, not 0) */
    int64_t gm_repairs;         /* repair PASSES executed, summed over slices --
                                 * not the number of slices repaired, which is
                                 * gm_slices below.  An earlier revision reported
                                 * this as "slices re-coded", which it never was:
                                 * a slice that needs four passes counted four
                                 * times, so the figure ran ahead of the number
                                 * of slices in a frame and read as nonsense. */
    int64_t gm_slices;          /* distinct slices the repair touched */
    int64_t gm_fallbacks;       /* slices the gentle rule could not finish, and
                                 * which were therefore repaired again from
                                 * their original coefficients with the harsh
                                 * uncapped rule (see gm_fellback) */
    int64_t gm_unfixed;         /* slices still out of gamut when the budget ran out */
    /* [V15] enforced total-pass accounting.  hist is indexed by per-slice
     * total, saturating at the last bin; 256 ints = 1024 bytes, which bounds
     * the memory regardless of gamut_strict (max total is 16*(3+redomax)). */
    int gm_total_cap;           /* (3 + omc_gm_redomax) * gamut_strict, or the probe */
    int gm_total_probe;         /* the test probe's value, 0 = unset */
    int gm_total_max;           /* worst per-slice total seen */
    int64_t gm_total_n;         /* repaired slices counted into hist */
    int64_t gm_capstops;        /* slices where the cap refused a fresh budget */
    int gm_total_hist[256];
    int32_t *gm_buf[OMC_NPLANES];   /* repair mask, summed-area (see the repair) */
    int64_t *gm_asat[OMC_NPLANES];  /* summed-area table of |residual|, the
                                     * normaliser that turns the alignment score
                                     * into a ratio in [-1, 1] (see gm_align) */
    int64_t *gm_rsat[OMC_NPLANES];  /* summed-area table of the RESIDUAL of every
                                     * pixel: how far out of the legal range it is
                                     * and in which direction (positive = above the
                                     * ceiling and must come down).  The count mask
                                     * above says WHICH coefficients are suspects;
                                     * this says whether reducing one of them helps
                                     * or hurts, and by how much. */
    uint8_t *gm_mask[OMC_NPLANES];  /* mode 13: every pixel this slice has EVER
                                     * committed out of range, accumulated over
                                     * the attempts.  Restoring the original
                                     * each attempt un-fixes what earlier
                                     * attempts fixed unless the mask remembers
                                     * them, which is why this is a union and
                                     * not the latest pass's findings. */
    int32_t *gm_save[OMC_NPLANES][2]; /* the slice's UNTOUCHED intra and delta
                                       * coefficients (mode 13): every repair
                                       * attempt is made from the original
                                       * rather than on top of the last one */
    uint16_t *gm_rowsave[OMC_NPLANES]; /* previous slice's last committed row */
    /* [LEGACY-REPAIR] END struct fields */
    int32_t *pbuf[OMC_NPLANES];             /* prediction transform scratch */
    int32_t *pcoef[OMC_NPLANES][OMC_NBANDS]; /* prediction coefficients */
    uint8_t *q5b[OMC_NPLANES][OMC_NBANDS];   /* Q5F per-block skip flags */
    int32_t *q5qs;   /* Q5F scratch q for the lock trial */
    int32_t *dcoef[OMC_NPLANES][OMC_NBANDS]; /* delta (inter) coefficients */
    uint8_t *elig[OMC_NPLANES][OMC_NBANDS]; /* OMC_GR noise-class maps, bands 7-9 */
    int dz_enabled, gr_enabled; /* per-instance (cfg-derived; env overrides) */
    /* causal in-frame rate banking (encoder-side only; decoder is stateless).
     * spent_bits counts wire bits emitted so far this frame. */
    int64_t spent_bits;
    int expect_slice; /* enforces in-order slice calls */
    /* lattice work buffers for the generation lock (per instance: these were
     * function-local statics, which made omc_enc_slice non-reentrant across
     * encoder instances - fixed 2026-07-28, verified by the interleaved
     * two-instance unit test and byte-identical reference streams) */
    int lat_cs[2][OMC_NPLANES][OMC_NBANDS][OMC_LAT_MAXCH];
    int lat_csn[OMC_NPLANES][OMC_NBANDS];
    band_cost_t bandcost[2][OMC_NPLANES][OMC_NBANDS];
    /* v4.7 plan hysteresis (encoder-only, env OMC_PLAN_HYST): previous
     * frame's committed plan + fill state per slice. Reused verbatim on
     * near-static inter slices when it still fits the budget, so the fill
     * amplitude field stops pulsing with rate-control jitter. */
    uint8_t *hyst_valid;      /* per slice */
    int16_t *rhyst_Q, *rhyst_steps, *rhyst_prof, *rhyst_partial;
    uint8_t *rhyst_valid;     /* sect.B2c: the slice's PREVIOUS REFRESH plan */
    uint8_t *rcyc_static;     /* sect.B2c: every inter frame since that refresh
                               * took the static hold (post-refresh frame exempt) */
    int16_t *hyst_Q, *hyst_steps, *hyst_partial, *hyst_prof;
    int32_t *tpq;             /* sect.B3c: quantised-LL scratch for the selector */
    uint32_t *hyst_fmask;
    uint32_t *hyst_fmask2;   /* sect.78.12.4 */
    uint8_t *hyst_gain;      /* nslices x OMC_NPLANES */
    int16_t *dc_q8;          /* OMC_DCFB: per (slice, plane) measured mean recon
                                offset of the previous frame, q8 fixed point */
    int16_t *dc_off;         /* OMC_DCFB>=2: per (slice, plane) deliberate LL
                                offset (integral controller state, q8): the
                                coded LL sits at src_LL + off so the pixel
                                mean cancels the synthesis-rounding bias */
    uint16_t *dc_scr[OMC_NPLANES]; /* OMC_DCFB=3: provisional-reconstruction
                                scratch (one slice), for the exact two-pass
                                per-slice DC measurement */
    int64_t *sl_energy;      /* per-slice LUMA sum|coef| of the previous frame */
    int64_t *sl_energy_c;    /* per-slice CHROMA sum|coef| of the previous frame */
    int64_t sl_energy_tot, sl_energy_tot_c;   /* frame totals (previous frame) */
    int64_t sl_energy_acc, sl_energy_acc_c;   /* accumulators, current frame */
    /* spatial plan coherence (OMC_SPC): previous slice's committed plan
     * within the CURRENT frame, for refinement-depth clamping */
    int spc_prof, spc_Q, spc_ns, spc_valid;
    omc_lockcand_t lcand[OMC_LOCK_CANDS]; /* T5 lock candidates (per slice) */
    int nlcand;
    uint8_t *spc_drop;  /* per slice*plane fill-bit drop count (v4c servo) */
    uint8_t *spc_kmax;  /* per slice*plane drop ceiling (kill-floor ratchet) */
    uint32_t spc_fmask;
    int spc_gain[OMC_NPLANES];
    int sl_energy_valid;
    size_t heap_at_create; /* footprint-instrumentation baseline only */
};

/* banking parameters (normative for the latency bound, see docs/LATENCY.md):
 * prefix sum of emitted bits through slice k never exceeds (k+1)*bits_per_slice
 * + OD_CAP_NUM/OD_CAP_DEN * bits_per_slice. */
/* OD_CAP_PCT = 0 since 2026-08-12: the banking overdraft was half a slice and
 * cost 0.5 slice periods of the A2 budget.  Measured neutral in quality, exact
 * CBR untouched, retry counts unchanged, tail-debt signature improved.
 * Tightening is backward-compatible (BITSTREAM sect 5 is an UPPER bound);
 * decoders keep the wider tolerance and the per-slice wire cap is unchanged.
 * There is no knob: the prefix bound is (k+1)*bits_per_slice, full stop. */
#define OD_CAP_PCT 0
#define OMC_QUALITY_FLOOR_Q 3 /* stop refining below (Q=3, all steps): bank bits */

struct omc_dec {
    ctx_common_t c;
    int32_t *sbuf[OMC_NPLANES];
    int32_t *tmp;
    uint8_t *pad; /* padded slice copy for safe backward reads */
    uint8_t *rowsig; /* per-band previous-row significance (2D context) */
    uint16_t *ref[OMC_NPLANES]; /* CURRENT frame, committed slice by slice
        (cross-slice terms + display copy; T5: never a prediction source) */
    uint16_t *refprev[OMC_NPLANES]; /* previous frame FINAL (prediction source) */
    /* [A1-MVBLK] design A: the decoder repeats the encoder's block-vector
     * derivation, which needs the frame BEFORE the prediction reference.  LUMA
     * ONLY -- the derivation never touches chroma -- so this is one extra luma
     * frame store, not a second full reference. */
    uint16_t *refprev2;
    int prom_chain; /* consecutive frame promotions held (capped at 2) */
    int cur_fidx8; /* fidx8 of the frame ref[] is accumulating (-1 = none) */
    int ddr_fidx;       /* [D-DDR] frames seen by the DDR model */
    int ddr_new_frame;  /* [D-DDR] set when the reference picture rotates */
    int32_t *pbuf[OMC_NPLANES];
    int32_t *pcoef[OMC_NPLANES][OMC_NBANDS];
    uint8_t *q5b[OMC_NPLANES][OMC_NBANDS];   /* Q5F per-block skip flags */
    /* error-concealment state (decoder-only; never affects a clean decode).
     * conceal_mode: 0 = freeze (hold previous frame for a lost slice, the
     * v4.1 behavior); 1 = motion-compensated + spatial (default). Per-frame
     * bookkeeping captured from the slices that DID decode, used to fill the
     * ones that did not. */
    int conceal_mode;
    uint8_t *slice_got;    /* [nslices] 1 if this slice decoded this frame */
    uint8_t *slice_inter;  /* [nslices] 1 if the decoded slice used prediction */
    int8_t *slice_mvx;     /* [nslices*OMC_NREG] captured half-pel H vectors */
    int8_t *slice_mvy;     /* [nslices*OMC_NREG] captured half-pel V vectors */
    uint16_t *state_hash;  /* [S3-HASH] [nslices] hash of the rows this decoder committed */
    uint8_t *state_bad;    /* [S3-HASH] [nslices] 1 = state did not match the encoder's */
    int frames_seen;       /* [S3-HASH] frames decoded (the first has no previous state) */
};

int omc_num_slices(const omc_config_t *cfg) { return cfg->height / cfg->slice_h; }
int omc_chroma_width(const omc_config_t *cfg)
{
    return cfg->chroma == OMC_CF_422 ? cfg->width / 2 : cfg->width;
}

static int xsl_lim_for(const omc_config_t *cfg);

static void common_init(ctx_common_t *c, const omc_config_t *cfg)
{
    c->cfg = *cfg;
    /* CAP_RULE_REVIEW F1: per-CONTEXT, never a process-wide global -- a
     * multi-channel server runs contexts at different rates in one process. */
    c->xsl_lim = xsl_lim_for(cfg);
    {   /* sect.B1(v5.3.5): rate rung for the fill divisor; see the field. */
        int64_t T = (int64_t)cfg->width * omc_resolve_slice_h(cfg)
                    * (cfg->chroma == OMC_CF_444 ? 3 : 2);
        int64_t b8 = 8 * (int64_t)cfg->bits_per_slice;
        int r = 0;
        /* sect.B5(v5.3.5): the CHROMA levers (offer threshold, eligibility)
         * engage one notch below the luma rung: 4:4:4 at 0.5 display bpp is
         * 0.167 b/cs -- rung 0 -- yet its chroma flatness stands at 3.75/4.45
         * %% (the v5.3 residue), and the rung-1 chroma treatment closes it to
         * 0.00 at +1.63 NEG (measured).  crung = 1 from 0.125 b/cs. */
        if      (4 * (int64_t)cfg->bits_per_slice >= 3 * T) r = 2; /* >= 0.75 b/cs */
        else if (2 * b8 >= 5 * T)                           r = 1; /* >= 0.3125:
                     * the 48-cell battery pinned the class boundary (sect.B1.5
                     * item 3): 0.25 b/cs -- every 0.5bpp 4:2:2 cell -- is clean
                     * at rung 0, while 0.333 (4:4:4 at 1.0 display bpp) keeps
                     * Y 8.42% flat un-fixed; 5/16 splits the anchors. */
        c->fill_rung = r;
        c->fill_crung = r >= 1 ? r : (8 * b8 >= T ? 1 : 0);   /* >= 0.125 b/cs */   /* pure function of the stream config; the A/B
                             * env is honoured at the ENCODER's set-site only —
                             * the decoder follows the stream (minor 14 ⇒ rung
                             * semantics) and never reads the environment, so
                             * no conformance-freeze entry is needed */
    }
    c->W = cfg->width;
    c->H = cfg->height;
    c->Wc = omc_chroma_width(cfg);
    /* Resolve automatic slice height here too: a library caller passing
     * slice_h = 0 ("auto") previously reached this line with a literal zero. */
    c->sh = omc_resolve_slice_h(cfg);
    c->nslices = omc_num_slices(cfg);
    c->mid = 1 << (cfg->bitdepth - 1);
    c->maxv = (1 << cfg->bitdepth) - 1;
    c->slice_bytes = cfg->bits_per_slice / 8;
    c->payload_bytes = c->slice_bytes - OMC_SLICE_HDR_BYTES;
}

static int plane_width(const ctx_common_t *c, int p) { return p == 0 ? c->W : c->Wc; }

/* ------------------------------------------------------------------ header */


extern int omc_xsl;   /* declared with the band-fix globals below */
int omc_write_stream_header(const omc_config_t *cfg, uint8_t *dst)
{
    memset(dst, 0, OMC_STREAM_HDR_BYTES);
    uint8_t *o = dst;
    uint32_t m = OMC_MAGIC;
    memcpy(o, &m, 4); o += 4;
    *o++ = OMC_VERSION_MAJOR;
    /* T5: every stream is minor 10.  There is no lower minor to fall back
     * to — XSL is always on and the temporal semantics are T5's.
     * sect.B1(v5.3.5): minor 14's ONE normative delta vs 13 is the luma fill
     * divisor rung.  With the encoder A/B lever OMC_FILLRUNG=0 the emitted
     * SEMANTICS are exactly v5.3's, so the header says so: the stream is
     * stamped minor 13 and decodes on a v5.3 decoder byte-for-byte, while
     * this build's strict single-minor decoder refuses it LOUDLY instead of
     * silently applying rung amplitudes the encoder never used. */
    *o++ = omc_fillrung ? OMC_MINOR_T5 : OMC_MINOR_T5 - 1;
    memcpy(o, &cfg->width, 2); o += 2;
    memcpy(o, &cfg->height, 2); o += 2;
    *o++ = cfg->bitdepth;
    *o++ = (uint8_t)cfg->chroma;
    *o++ = cfg->slice_h;
    memcpy(o, &cfg->fps_num, 2); o += 2;
    memcpy(o, &cfg->fps_den, 2); o += 2;
    *o++ = cfg->color.primaries; *o++ = cfg->color.transfer;
    *o++ = cfg->color.matrix;   *o++ = cfg->color.full_range;
    memcpy(o, &cfg->bits_per_slice, 4); o += 4;
    *o++ = cfg->refresh_r ? cfg->refresh_r : 8;
    /* bytes 26-31.  Byte 26 is scan_type and stays RESERVED 0: it is held by
     * scan_type, whose values 0/1/2 are ALREADY ALLOCATED (docs/BITSTREAM.md
     * 9.3), so putting uc_ratio's 0/1/2 there would have collided value for
     * value.  A byte written zero is not the same as a byte unassigned.
     * Bytes 28-31 carry display_width/height.  The only free space is byte
     * 27's reserved
     * bits 3-7, which is where both v4.8 fields live:
     *
     *   byte 27  bit 0    rct
     *            bit 1    grain_corr
     *            bit 2    RESERVED, must be zero (was fill_static in minor 11;
     *                     minor 12 makes the static fill tile the only
     *                     behaviour, so the bit no longer selects anything)
     *            bits 3-4 uc_ratio  (0 none, 1 = 2x, 2 = 4x)
     *            bits 5-6 tf_mode   (0 off, 1/2 = OMC-TF strength)
     *            bit 7    reserved 0
     *
     * Both are zero on every pre-v4.8 stream, so byte 27 is unchanged and the
     * nine conformance hashes stand.  tf_mode is what makes the temporal filter
     * INTEROPERABLE: without it the decoder cannot know the encoder filtered,
     * decodes silently, and drifts from the encoder's reconstruction. */
    *o++ = 0;                                     /* 26: scan_type, reserved */
    /* T5: tf_mode bits 5-6 are DEAD (the in-loop temporal filter was removed
     * with the old temporal engine) and are written 0 always. */
    *o++ = (uint8_t)((cfg->rct ? 1 : 0) | (cfg->grain_corr ? 2 : 0) |
                     ((cfg->uc_ratio & 3) << 3));
    memcpy(o, &cfg->display_height, 2); o += 2;
    memcpy(o, &cfg->display_width, 2); o += 2;
    return OMC_STREAM_HDR_BYTES;
}

int omc_read_stream_header(const uint8_t *src, omc_config_t *cfg)
{
    uint32_t m;
    memcpy(&m, src, 4);
    if (m != OMC_MAGIC) return -1;
    if (src[4] != OMC_VERSION_MAJOR) return -2;
    /* T5 decodes minor 10 ONLY.  Earlier minors carry the removed temporal
     * engine's semantics (rolling reference, block MV, optional XSL levels)
     * and would silently mis-decode; they are rejected instead. */
    if (src[5] != OMC_MINOR_T5) return -2;
    memset(cfg, 0, sizeof(*cfg));
    cfg->ver_minor = src[5];
    const uint8_t *o = src + 6;
    memcpy(&cfg->width, o, 2); o += 2;
    memcpy(&cfg->height, o, 2); o += 2;
    cfg->bitdepth = *o++;
    cfg->chroma = (omc_chroma_t)*o++;
    cfg->slice_h = *o++;
    memcpy(&cfg->fps_num, o, 2); o += 2;
    memcpy(&cfg->fps_den, o, 2); o += 2;
    cfg->color.primaries = *o++; cfg->color.transfer = *o++;
    cfg->color.matrix = *o++;   cfg->color.full_range = *o++;
    memcpy(&cfg->bits_per_slice, o, 4); o += 4;
    cfg->refresh_r = *o++;
    if (!cfg->refresh_r) cfg->refresh_r = 8;
    if (*o++ != 0) return -3;      /* byte 26: scan_type, reserved 0 */
    cfg->rct = (uint8_t)(*o & 1);
    cfg->grain_corr = (uint8_t)((*o >> 1) & 1);
    cfg->uc_ratio = (uint8_t)((*o >> 3) & 3);
    /* T5: tf_mode bits (5-6) and bit 7 must be zero — the in-loop temporal
     * filter no longer exists.  A stream with them set is not a T5 stream. */
    if ((*o >> 5) != 0) return -3;
    o++;
    if (cfg->uc_ratio > 2) return -3;
    memcpy(&cfg->display_height, o, 2); o += 2;
    memcpy(&cfg->display_width, o, 2); o += 2;
    /* VALIDATE THE WIRE FIELDS.  Everything above is copied verbatim out of an
     * untrusted header, and the reference decoder never calls
     * omc_validate_config, so nothing else checks them.  Unchecked, a crafted
     * stream reaches real damage: slice_h 128 overflows dwt.c's per-column
     * stack buffers (demonstrated under AddressSanitizer), bitdepth 0 or > 32
     * makes 1 << (bitdepth-1) undefined, height 0 gives a zero slice count and
     * hangs the tool, and bits_per_slice below the wire floor underflows
     * payload_bytes.  The CRC is no defence -- an attacker computes it.  These
     * are the same constraints omc_validate_config enforces encoder-side,
     * applied where the trust boundary actually is. */
    if (cfg->bitdepth != 8 && cfg->bitdepth != 10 && cfg->bitdepth != 12)
        return -3;
    if (cfg->chroma != OMC_CF_422 && cfg->chroma != OMC_CF_444) return -3;
    if (cfg->slice_h != 8 && cfg->slice_h != 16 && cfg->slice_h != 32) return -3;
    if (cfg->width < 64 || cfg->width > 8192) return -3;
    if (cfg->width % (cfg->chroma == OMC_CF_444 ? 32 : 64)) return -3;
    if (cfg->height < cfg->slice_h || cfg->height > 8192) return -3;
    if (cfg->height % cfg->slice_h) return -3;
    if (cfg->display_width > cfg->width) return -3;
    if (cfg->display_height > cfg->height) return -3;
    if (cfg->bits_per_slice % 8) return -3;
    if (cfg->bits_per_slice < (uint32_t)(OMC_SLICE_HDR_BYTES + 4) * 8) return -3;
    if ((uint64_t)cfg->bits_per_slice > (uint64_t)cfg->width * cfg->slice_h * 48)
        return -3;
    if (cfg->uc_ratio && (uint64_t)cfg->width << cfg->uc_ratio > 32768) return -3;
    return OMC_STREAM_HDR_BYTES;
}

/* Derive per-band shifts from (Q, n_steps, partial info). partial_band gets
 * `partial_chunks` leading chunks at shift-1. Returns shifts and partial pos. */
typedef struct {
    int shift[OMC_NPLANES][OMC_NBANDS];
    int partial_p, partial_b, partial_chunks; /* -1 if none */
    /* sect.B3c(v5.3.5) TARGETED PARTIAL: when sel_on, the partial_chunks
     * refined chunks are sel[]'s rank-prefix (chunks ranked by the plane's
     * QUANTISED-LL gradient, best first), not the scan-order prefix.  The
     * ranking is a pure function of bits both ends share, so encoder,
     * decoder, lock_verify and the candidate scan all derive it identically
     * (the sect.62 rule: one helper, every site). */
    int sel_on;
    uint8_t sel[OMC_LAT_MAXCH];      /* sel[ci] = 1 -> chunk ci refined */
    int16_t rank[OMC_LAT_MAXCH];     /* chunk indices, best first */
    int rank_n;
    /* sect.B3d(v5.3.5) PBAND: when pband >= 0, the k refined chunks live in
     * the NAMED coarse band (omc_pband_tab[pband]) instead of the refine
     * order's step band -- the syntax the wash needs (sect.B3.5c: the fixed
     * order can never point refinement at the coarse-band roundings that
     * draw block-mean washes).  Carried in the header's partial16 field as
     * [flag:1][band:3][k:12]; zero layout change, minor-14 rider. */
    int pband;                       /* -1 = legacy; else table index 0..7 */
    int pdepth;                      /* sect.B3d: rungs of refinement on the
                                      * selected chunks (1..4) -- one rung is
                                      * measured useless for the wash (zeroed
                                      * coefficients stay zero at s-1). */
} shift_plan_t;

static void derive_shifts(int cf444, int prof, int Q, int n_steps, int partial_chunks,
                          shift_plan_t *sp)
{
    for (int p = 0; p < OMC_NPLANES; p++)
        for (int b = 0; b < OMC_NBANDS; b++) {
            int s = Q + omc_off[prof][p][b] + ((cf444 && p > 0) ? omc_off_c444[b] : 0);
            if (s < 0) s = 0;
            if (s > OMC_MAX_SHIFT) s = OMC_MAX_SHIFT;
            if (b == 0 && s > OMC_LL_CAP) s = OMC_LL_CAP;
            sp->shift[p][b] = s;
        }
    for (int i = 0; i < n_steps && i < omc_refine_steps; i++) {
        int p = omc_refine_order[i][0], b = omc_refine_order[i][1];
        if (sp->shift[p][b] > 0) sp->shift[p][b]--;
    }
    sp->partial_p = sp->partial_b = -1;
    sp->partial_chunks = 0;
    sp->sel_on = 0; sp->rank_n = 0; sp->pband = -1; sp->pdepth = 1;
    /* sect.B3d: unpack [flag:1][band:3][k:12].  The table is FIXED and
     * normative: the coarse bands where block-mean washes are drawn.  LL is
     * excluded (OMC_LL_CAP owns it). */
    static const int8_t omc_pband_tab[8][2] =
        { {0,1},{0,2},{0,3},{1,1},{1,2},{2,1},{2,2},{0,3} };
    if (partial_chunks & 0x8000) {
        int t = (partial_chunks >> 12) & 7;
        int dep = ((partial_chunks >> 10) & 3) + 1;
        int k = partial_chunks & 0x03FF;
        int p = omc_pband_tab[t][0], b = omc_pband_tab[t][1];
        if (k > 0 && sp->shift[p][b] > 0) {
            sp->partial_p = p;
            sp->partial_b = b;
            sp->partial_chunks = k;
            sp->pband = t;
            sp->pdepth = dep <= sp->shift[p][b] ? dep : sp->shift[p][b];
        }
        return;
    }
    if (partial_chunks > 0 && n_steps < omc_refine_steps) {
        int p = omc_refine_order[n_steps][0], b = omc_refine_order[n_steps][1];
        if (sp->shift[p][b] > 0) {
            sp->partial_p = p;
            sp->partial_b = b;
            sp->partial_chunks = partial_chunks;
            /* FDBG-BEGIN */
            extern int omc_fdbg;
            if (omc_fdbg) {
                extern int64_t fdbg_part_any, fdbg_part_fillband;
                fdbg_part_any++;
                if (b >= OMC_FILL_BANDS_FROM) fdbg_part_fillband++;
            }
            /* FDBG-END */
        }
    }
}

extern int omc_chromabias;   /* chroma detail bias (test lever, defined below) */
extern int omc_bandtilt;     /* fine-band precision tilt (defined below) */
/* shift for coefficient index i of band (p,b) under plan sp */
/* One step of the gamut repair's reduction of a single coefficient.  `step`
 * is 0 for the proportional form (scale by num/den) and the quantizer step for
 * the subtractive form.  Both are monotone toward zero and neither can change
 * a coefficient's sign, which is what keeps the repair loop convergent. */
/* OMC_GM_STAT counters.  Deliberately globals rather than per-context state:
 * they exist only to answer a question about where the repair's cost lives and
 * are never read on any coding path. */
/* ==== [LEGACY-REPAIR] BEGIN: helpers of the iterative in-gamut repair (v5.0-v5.3). Kept only as the
 * fallback behind the constructive legality step [S2-STEP] (src/latt_probe.inc). Removal condition:
 * the step closes 100% of slices on the full battery -- then delete everything between the
 * BEGIN/END markers, the tagged levers, struct fields, API and docs (LEGACY_REPAIR_INVENTORY.md). ==== */
static int64_t gm_st_cand, gm_st_veto, gm_st_red, gm_st_cross;
static int64_t gm_st_cross_b[OMC_NBANDS], gm_st_red_b[OMC_NBANDS];
static int64_t gm_st_cross_m[8], gm_st_red_m[8];
/* Total change in CODED VALUE, and the squared reconstruction error that change
 * injects.  The crossing COUNT turned out not to rank the arms: on 4K graphics
 * fewer crossings scored better, on 4K cinema more crossings scored better,
 * because a proportional cut moves q by many steps at once while a capped one
 * moves it by exactly one.  What is common to both is how much reconstruction
 * energy leaves the picture, which is sum over crossings of (dq << s)^2 times
 * the band's ||g||^2 -- so both halves are recorded and the weighting is done
 * outside, against the measured per-band energies. */
static int64_t gm_st_dq[OMC_NBANDS], gm_st_e2[OMC_NBANDS];
static int64_t gm_st_pickA, gm_st_pickB;   /* trial selection outcome */

extern int omc_gm_stat;

/* Record what one reduction really did.  A reduction that does not carry the
 * coefficient across a quantizer boundary emits the same q, therefore the same
 * bits and the same reconstruction: it is free.  Counting reductions instead of
 * crossings measures work, not damage. */
static void gm_stat_note(int b, int32_t before, int32_t after, int s)
{
    int32_t qb = omc_quant1b(before, s, 0), qa = omc_quant1b(after, s, 0);
    int32_t m = before < 0 ? -before : before;
    int bucket = 0;
    int32_t step = (int32_t)1 << s;
    while (bucket < 7 && m >= (step << bucket)) bucket++;
    gm_st_red++; gm_st_red_b[b]++; gm_st_red_m[bucket]++;
    if (qa != qb) {
        gm_st_cross++; gm_st_cross_b[b]++; gm_st_cross_m[bucket]++;
        int64_t dq = qa > qb ? qa - qb : qb - qa;
        int64_t dr = dq << (s < 30 ? s : 30);
        gm_st_dq[b] += dq;
        gm_st_e2[b] += dr * dr;
    }
}

/* Squared error between the EMITTED picture of one slice and the source it was
 * made from, summed over all three planes and every visible row.  This is the
 * quantity the repair's shape selection is judged on: not a proxy for closeness
 * to the source, but closeness to the source. */
static int64_t gm_slice_sse(const omc_frame_t *in, const omc_frame_t *rec,
                            const int *pw_of, int nplanes, int row0, int nrows,
                            int masked)
{
    int64_t sse = 0;
    for (int p = 0; p < nplanes; p++) {
        int pw = pw_of[p];
        if (masked < 2) {          /* 1 = plain squared error */
            for (int r = 0; r < nrows; r++) {
                const uint16_t *a = in->p[p]  + (size_t)(row0 + r) * in->stride[p];
                const uint16_t *b = rec->p[p] + (size_t)(row0 + r) * rec->stride[p];
                for (int x = 0; x < pw; x++) {
                    int64_t d = (int64_t)a[x] - b[x];
                    sse += d * d;
                }
            }
            continue;
        }
        /* MASKED distance, in 8x8 blocks.  Plain squared error is the wrong
         * distance for this decision and the measurement says so: on the 4K
         * graphics master it picks the gentle shape and scores 97.81, where the
         * harsh shape scores 98.07.  Error is not equally visible everywhere --
         * an error of a given size in a flat part of the picture is far more
         * visible than the same error inside texture, and ringing beside a hard
         * edge lands in exactly the flat part.  An anti-gaming perceptual model
         * refuses to credit detail the source did not have, so it charges that
         * ringing at close to full price while charging error inside texture at
         * a discount.  Dividing each block's squared error by the block's own
         * source activity is the cheapest honest version of that, and it needs
         * nothing but the source. */
        for (int r0 = 0; r0 < nrows; r0 += 8) {
            int rh = nrows - r0 < 8 ? nrows - r0 : 8;
            for (int c0 = 0; c0 < pw; c0 += 8) {
                int cw = pw - c0 < 8 ? pw - c0 : 8;
                int64_t bs = 0, act = 0;
                for (int r = 0; r < rh; r++) {
                    const uint16_t *a = in->p[p]  + (size_t)(row0 + r0 + r) * in->stride[p] + c0;
                    const uint16_t *b = rec->p[p] + (size_t)(row0 + r0 + r) * rec->stride[p] + c0;
                    const uint16_t *an = (r + 1 < rh)
                        ? in->p[p] + (size_t)(row0 + r0 + r + 1) * in->stride[p] + c0 : 0;
                    for (int x = 0; x < cw; x++) {
                        int64_t d = (int64_t)a[x] - b[x];
                        bs += d * d;
                        if (x + 1 < cw) { int32_t g = a[x + 1] - a[x]; act += g < 0 ? -g : g; }
                        if (an) { int32_t g = an[x] - a[x]; act += g < 0 ? -g : g; }
                    }
                }
                int n = rh * cw;
                if (!n) continue;
                int64_t am = act / n;                 /* mean |gradient| of the source */
                sse += bs * 256 / (16 + am);
                if (masked < 3) continue;
                /* ADDED DETAIL, charged separately.  The anti-gaming model this
                 * work is held to refuses to credit detail the source did not
                 * have -- that is the whole content of its two gain limits.
                 * Ringing IS detail the source did not have.  So a block whose
                 * reconstruction is BUSIER than its source is charged for the
                 * excess, and a block that is quieter than its source is not
                 * refunded for it.  Only the source and the reconstruction are
                 * needed; nothing about the content class is assumed. */
                int64_t ract = 0;
                for (int r = 0; r < rh; r++) {
                    const uint16_t *b = rec->p[p] + (size_t)(row0 + r0 + r) * rec->stride[p] + c0;
                    const uint16_t *bn = (r + 1 < rh)
                        ? rec->p[p] + (size_t)(row0 + r0 + r + 1) * rec->stride[p] + c0 : 0;
                    for (int x = 0; x < cw; x++) {
                        if (x + 1 < cw) { int32_t g = b[x + 1] - b[x]; ract += g < 0 ? -g : g; }
                        if (bn) { int32_t g = bn[x] - b[x]; ract += g < 0 ? -g : g; }
                    }
                }
                int64_t excess = ract - act;
                if (excess > 0) sse += excess * excess / n;
            }
        }
    }
    return sse;
}

/* Transform-domain distance for the trial selection (OMC_GM_TRIAL=4).
 *
 * WHY A FOURTH ONE.  Three pixel-domain distances -- plain squared error,
 * squared error masked by source activity, and squared error plus a penalty for
 * detail the source did not have -- all pick the SAME shape on every slice of
 * the 4K graphics master, and the shape they pick scores 0.29 lower on
 * VMAF-NEG.  That is not a tuning failure: the shape they pick really is 3.3 dB
 * closer to the source (43.90 dB against 40.58 dB PSNR).  On that content
 * fidelity and the metric point in opposite directions.
 *
 * Breaking the metric into its components says exactly which part disagrees.
 * Between the two shapes, VIF barely moves and motion does not move at all;
 * the whole 0.29 is ADM, and almost all of it is ADM at the two COARSE scales
 * (scale 2: -0.0099, scale 3: -0.0121).  ADM separates an impairment into
 * detail LOST from the source and detail ADDED that the source never had, and
 * with the enhancement gain limit set to 1.0 it refuses to credit the added
 * kind.  Quantization overshoot past a rail is added detail by definition.
 *
 * So this distance is built the way ADM is: per band, the magnitude the source
 * had but the reconstruction lost, plus K times the magnitude the
 * reconstruction has that the source never had, each weighted by that band's
 * measured picture energy.  Both quantities are already in hand -- the
 * untouched source coefficients in gm_save and the committed reconstruction in
 * sbuf -- so it costs one sweep of the slice and no model. */
static int64_t gm_slice_adm(const int32_t *const *save, const int32_t *sbuf,
                            int pw, int sh, int K)
{
    static const int64_t g2[OMC_NBANDS] =
        { 590942, 173111, 96074, 55229, 33853, 26841, 10294, 11792, 10100, 4840 };
    omc_band_t bl[OMC_NBANDS];
    omc_band_layout(pw, sh, bl);
    int64_t cost = 0;
    size_t off = 0;
    for (int b = 0; b < OMC_NBANDS; b++) {
        const omc_band_t *B = &bl[b];
        int64_t loss = 0, add = 0;
        for (int r = 0; r < B->h; r++)
            for (int x = 0; x < B->w; x++) {
                int32_t sv = save[0][off + (size_t)r * B->w + x];
                int32_t rv = sbuf[(size_t)(B->r0 + r) * pw + B->c0 + x];
                if (sv < 0) sv = -sv;
                if (rv < 0) rv = -rv;
                if (sv > rv) loss += sv - rv; else add += rv - sv;
            }
        cost += g2[b] * (loss + (int64_t)K * add) / 10000;
        off += (size_t)B->h * B->w;
    }
    return cost;
}

/* ---- the alignment test (mode 16) --------------------------------------
 *
 * Every shape from mode 0 to mode 15 reduced EVERY coefficient whose support
 * covers an offending pixel.  None of them asked the one question that decides
 * whether the reduction is worth anything: does reducing this coefficient move
 * that pixel TOWARD the legal range, or further out of it?
 *
 * Reducing a coefficient's magnitude by d changes the reconstruction at pixel
 * q by  -sign(c) * d * g(q), where g is the synthesis basis of that
 * coefficient.  A sample above the ceiling has to come DOWN and a sample below
 * the floor has to go UP, so a reduction only helps where
 * sign(c) * g(q) has the same sign as the sample's excursion.  Where it does
 * not, the reduction pushes the offending sample further out of range AND
 * still costs picture -- the worst of both.  On measured content roughly half
 * of every pass was doing exactly that.
 *
 * The test needs no magnitudes from the coefficient, only the basis, and the
 * basis is exactly separable and exactly shift-invariant in the interior (both
 * verified by impulse response: separability error 0.00e+00 of peak, no sign
 * disagreement, no support-box disagreement, over 28-35 phases per band).  So
 * g(j, i) = gy[j] * gx[i], both factors are run-length compressed by sign in
 * GM_BASIS, and the score
 *
 *      score = sign(c) * SUM over offending q of  residual(q) * g(q)
 *
 * collapses to a weighted sum over at most ny*nx rectangles, each of which is
 * four lookups into a summed-area table of residuals.  ny <= 3 and nx <= 7, so
 * the whole test is at most 84 lookups.
 *
 * Weighting by RESIDUAL rather than by a count of offending pixels matters:
 * feasibility is a max, not a sum.  One pixel forty codes out is worth more
 * than ten pixels one code out, and a coefficient that fixes the worst
 * offender while nudging ten marginal pixels is usually the right move.  It
 * also handles, with no special case, a coefficient whose support covers both
 * an above-ceiling region and a below-floor region: the two contributions have
 * opposite signs and net out, which is the honest answer.  That case is not
 * exotic -- it is exactly what G-T5-GAMUT2c's rail-on-boundary content makes.
 *
 * Returns the score for a POSITIVE coefficient; the caller flips it for a
 * negative one.  Returns 1 (touch it) when the coefficient's support is
 * clipped by a slice or plane boundary: the whole-sample symmetric extension
 * reshapes the basis there and the interior table does not describe it.  That
 * is a deliberate fall-through rather than a guess -- it can only make the
 * repair do more work, never veto a coefficient it should have touched, and
 * the boundary rows are the ones the repair can least afford to get wrong. */
static int64_t gm_align(const gm_basis_t *G, const int64_t *rsat,
                        const int64_t *asat, int satw,
                        int sh, int pw, int ry, int cx, int vd, int hd,
                        int *no_veto, int64_t *mass)
{
    if (mass) *mass = 0;
    *no_veto = 1;
    /* The interior table does not describe a coefficient whose basis is
     * reshaped by the whole-sample symmetric extension at a slice or plane
     * boundary, and it does not describe a plane whose width does not divide
     * into the band grid the table was measured on.  Both fall through to
     * "touch it" -- never to "veto it", which at a boundary is the one place
     * the repair cannot afford to be wrong. */
    if (vd != G->vd || hd != G->hd) return 0;
    if (ry + G->sy0 < 0 || ry + G->sy1 >= sh ||
        cx + G->sx0 < 0 || cx + G->sx1 >= pw) return 0;
    *no_veto = 0;
    int64_t score = 0;
    for (int a = 0; a < G->ny; a++) {
        int y0 = ry + G->y[a].off, y1 = y0 + G->y[a].len;
        if (y0 < 0) y0 = 0;
        if (y1 > sh) y1 = sh;
        if (y0 >= y1) continue;
        int64_t wy = (int64_t)G->y[a].w * G->y[a].sgn;
        for (int b = 0; b < G->nx; b++) {
            int x0 = cx + G->x[b].off, x1 = x0 + G->x[b].len;
            if (x0 < 0) x0 = 0;
            if (x1 > pw) x1 = pw;
            if (x0 >= x1) continue;
            int64_t r = rsat[(size_t)y1 * satw + x1] - rsat[(size_t)y0 * satw + x1]
                      - rsat[(size_t)y1 * satw + x0] + rsat[(size_t)y0 * satw + x0];
            int64_t wxs = (int64_t)G->x[b].w * G->x[b].sgn;
            if (mass && asat) {
                int64_t am = asat[(size_t)y1 * satw + x1] - asat[(size_t)y0 * satw + x1]
                           - asat[(size_t)y1 * satw + x0] + asat[(size_t)y0 * satw + x0];
                *mass += (int64_t)G->y[a].w * G->x[b].w * am;
            }
            if (!r) continue;
            score += wy * wxs * r;
        }
    }
    return score * G->s0;
}

static inline int32_t gm_reduce(int32_t v, int num, int den, int32_t step)
{
    if (!step) return v * num / den;
    if (v > 0) { v -= step; return v < 0 ? 0 : v; }
    if (v < 0) { v += step; return v > 0 ? 0 : v; }
    return 0;
}

/* THE GENTLER OF THE TWO REDUCTIONS, per coefficient.
 *
 * The proportional shrink and the stepwise one are not "fast" and "gentle":
 * each is gentler than the other on different coefficients, and which is which
 * depends on the coefficient's size relative to its own quantizer step.  Taking
 * a quarter off a coefficient worth ten steps removes two and a half steps;
 * taking a quarter off one worth half a step removes an eighth of a step.  So
 * on starved 8-bit content, where steps are large and most coefficients are
 * small, the proportional shrink is the SMALLER move -- which is why it beat
 * every stepwise form on the 4K graphics master and lost to them everywhere
 * else.  That, and not any property of the content, was the density split.
 *
 * Taking the larger remaining magnitude takes the smaller reduction, per
 * coefficient, with no classification of anything.  It self-escalates for free:
 * the stepwise term grows with the pass count, so once it passes the
 * proportional one this reduces to the proportional shrink and convergence is
 * bounded by it. */
static inline int32_t gm_reduce_min(int32_t v, int num, int den, int32_t step)
{
    int32_t a = v * num / den;
    int32_t b = gm_reduce(v, num, den, step);
    int32_t aa = a < 0 ? -a : a, ab = b < 0 ? -b : b;
    return aa >= ab ? a : b;
}
/* ---- sect.51: the LL DC excursion bound -----------------------------------
 *
 * WHY THIS EXISTS.  The pixel domain handed to the forward transform is
 * CENTRED ON MID-GREY (`d[x] = src[x] - c->mid - OMC_REF_BIAS`), and the LL
 * band's DC gain to pixels is exactly 1 (measured; see the two-pass DC null).
 * So reducing an LL coefficient toward zero by D moves the level of its
 * ENTIRE support -- 4 picture rows by 32 picture columns at slice_h 16 --
 * by exactly D codes TOWARDS MID-GREY: dark content gets brighter, light
 * content gets darker, and the detail sitting on top of it is untouched.
 * That is precisely the artifact the owner reported (sect.50.1) and precisely
 * the signature sect.50.3 measured (level moves, local sd unchanged).
 *
 * The repair does not need that much movement: the violation it is chasing is
 * a handful of pixels, and every other band corrects them without moving a
 * level at all.  So bound the LL band's TOTAL excursion from the slice's
 * untouched coefficient, in picture codes, and let the detail bands do the
 * rest.  The bound is on the ENCODER's own policy, applies identically at
 * every generation, changes no bitstream syntax and no decoder rule.
 *
 * `orig` is the untouched value saved in gm_save on the slice's first repair
 * pass, so the bound is on the TOTAL reduction across all passes and across a
 * converging restart -- not per pass, which a cumulative rule would evade. */
static inline int32_t gm_llbound(int32_t orig, int32_t red, int32_t cap)
{
    int32_t d;
    if (cap <= 0) return red;
    d = red - orig;
    if (d >  cap) return orig + cap;
    if (d < -cap) return orig - cap;
    return red;
}

/* sect.51.5c: floor a detail-band reduction at `pct` % of the untouched
 * magnitude.  Sign-preserving; a coefficient that was zero stays zero. */
static inline int32_t gm_detfloor(int32_t orig, int32_t red, int pct)
{
    int32_t lim;
    if (pct <= 0) return red;
    lim = (int32_t)(((int64_t)(orig < 0 ? -orig : orig) * pct) / 100);
    if (red >= 0 && orig >= 0) return red < lim ? lim : red;
    if (red <= 0 && orig <= 0) return red > -lim ? -lim : red;
    return red;
}
/* ==== [LEGACY-REPAIR] END: helpers ==== */

/* ---- sect.B3c(v5.3.5): TARGETED PARTIAL selector.  Ranks the partial band's
 * chunks by the gradient of the plane's QUANTISED LL (raw q codes -- the LL
 * band has one shift, so ranking on q equals ranking on reconstructed values
 * and both ends hold identical integers by construction).  Score of a chunk =
 * sum over its coefficient columns of the LL column-gradient under them.
 * Deterministic: integer scores, ties broken by lower chunk index.  Pure
 * function of (llq, geometry) -- the same bits at encoder, decoder,
 * lock_verify and the candidate scan, so every generation derives the same
 * partition (the committed-derivability that makes fill-band partials legal
 * where the scan-order form never was; see the refine-loop note it replaces).
 * Returns the ranking into sp->rank/rank_n; omc_tpart_apply() then marks the
 * k-prefix in sp->sel. */
static void omc_tpart_rank(const int32_t *llq, int lstride, int llw, int llh,
                           int bw, int bn, shift_plan_t *sp)
{
    int nch = (bn + OMC_CHUNK - 1) / OMC_CHUNK;
    if (nch > OMC_LAT_MAXCH) nch = OMC_LAT_MAXCH;
    int64_t colg[512];  /* llw <= 512 at 8K (7680/2/... ) -- guarded below */
    int gw = llw < 512 ? llw : 512;
    for (int cl = 0; cl < gw; cl++) {
        int64_t g = 0;
        for (int r = 0; r < llh; r++) {
            int32_t c0 = llq[(size_t)r * lstride + cl];
            if (cl + 1 < llw) { int32_t d = llq[(size_t)r * lstride + cl + 1] - c0; g += d < 0 ? -d : d; }
            if (r + 1 < llh) { int32_t d = llq[(size_t)(r + 1) * lstride + cl] - c0; g += d < 0 ? -d : d; }
        }
        colg[cl] = g;
    }
    int64_t score[OMC_LAT_MAXCH];
    for (int ci = 0; ci < nch; ci++) {
        int64_t sc = 0;
        int end = (ci + 1) * OMC_CHUNK; if (end > bn) end = bn;
        for (int i = ci * OMC_CHUNK; i < end; i++) {
            int cl = (int)(((int64_t)(i % bw) * llw) / bw);
            if (cl >= gw) cl = gw - 1;
            sc += colg[cl];
        }
        score[ci] = sc;
    }
    for (int i = 0; i < nch; i++) sp->rank[i] = (int16_t)i;
    for (int i = 1; i < nch; i++) {          /* insertion sort, stable */
        int16_t v = sp->rank[i]; int j = i;
        while (j > 0 && (score[sp->rank[j-1]] < score[v] ||
               (score[sp->rank[j-1]] == score[v] && sp->rank[j-1] > v))) {
            sp->rank[j] = sp->rank[j-1]; j--;
        }
        sp->rank[j] = v;
    }
    sp->rank_n = nch;
}
static void omc_tpart_apply(shift_plan_t *sp, int k)
{
    memset(sp->sel, 0, sizeof(sp->sel));
    if (k > sp->rank_n) k = sp->rank_n;
    for (int i = 0; i < k; i++) sp->sel[sp->rank[i]] = 1;
    sp->sel_on = 1;
}
static inline int coeff_shift(const shift_plan_t *sp, int p, int b, int i)
{
    int s = sp->shift[p][b];
    if (omc_chromabias && p > 0 && b > 0) s += omc_chromabias;
    if (omc_bandtilt) {
        if (b >= 7) { s -= omc_bandtilt; if (s < 0) s = 0; }
        else if (b >= 1 && b <= 3) s += omc_bandtilt;
    }
    if (p == sp->partial_p && b == sp->partial_b && sp->sel_on
        ? sp->sel[(i >> 8) < OMC_LAT_MAXCH ? (i >> 8) : 0] && (i >> 8) < OMC_LAT_MAXCH
        : p == sp->partial_p && b == sp->partial_b && (i >> 8) < sp->partial_chunks) {
        s -= sp->pband >= 0 ? sp->pdepth : 1;   /* sect.B3d: PBAND depth */
        if (s < 0) s = 0;
    }
    return s;
}

/* ------------------------------------------------------------------ encoder */

int omc_dz_mode = 0; /* F-2 deadzone switch (env OMC_DZ=1); see internal.h */
/* ---- sect.54: PER-PLANE DEADZONE MASK (env OMC_DZ_PLANE, bit p = plane p).
 *
 * The deadzone kills a coefficient that quantises to |q| == 1 when its
 * magnitude is below 9/16 of a step, i.e. it takes the narrow slice of the
 * first bin between 0.5 and 0.5625 of a step and sends it to zero.  On LUMA
 * that is nearly free: luma detail coefficients are spread over many bins, so
 * the slice holds a small fraction of them and zeroing it buys real bits.
 *
 * On CHROMA it is not free, and the reason is that the threshold is a fraction
 * of a step while the PLANES ARE NOT ALIKE.  Chroma detail is low-energy: most
 * of it lives in the FIRST bin, right against the 0.5-step boundary, so the
 * same 1/16-of-a-step slice holds a large share of the plane's whole detail
 * population.  Zeroing a coefficient does not merely coarsen it -- it destroys
 * its CORRELATION with the source, which is why the effect is invisible to
 * every energy measure and to PSNR, and shows up only on h/fidelity.py.
 *
 * Measured on the gfx/DNG arm at 0.5 bpp (ledger sect.54.3): with the deadzone
 * lifted on chroma only, chroma TRUE DETAIL (correlation-weighted retention)
 * rises Cb 0.119 -> 0.141 and Cr 0.122 -> 0.132 while luma is unchanged --
 * because the bits come from chroma's own share, not from luma's.
 *
 * ENCODER-ONLY.  The decoder does q << s and has never seen this rule.
 * GENERATION EXACTNESS (A4) is preserved by the same argument the F-2 deadzone
 * and the calm kill both rest on: the test is a strict magnitude compare
 * against 9/16 of a step, and every coefficient of a previously-coded picture
 * is exactly q << s, i.e. exactly 1.0 steps for |q| == 1, which fails that
 * compare.  The rule cannot fire on a committed picture whether it is enabled
 * or not, so narrowing WHERE it may fire cannot change a re-encode.
 *
 * SHIPPED DEFAULT 7 = all planes, i.e. this lever is a NO-OP unless asked for,
 * and the build is byte-identical to v5.1.0 with it.  1 = luma only, which is
 * the measured chroma improvement (+27% Cb / +17% Cr true detail) and costs
 * 0.71 VMAF-NEG.  It is NOT the default because the standing requirement is
 * that a fix must not hurt VMAF-NEG, and a perceptual-vs-metric trade of this
 * size is reserved to the owner by PROJECT_CONSTRAINTS section E.  ledger sect.54.6 C1.
 *
 * OMC_DZ_CTO bounds WHERE the lift applies on a plane the mask excludes: the
 * deadzone is lifted only for bands with index <= OMC_DZ_CTO, and kept for the
 * bands above.  This exists because the lift is not equally worth its bits
 * everywhere.  The band rectangles grow geometrically -- band 1 is
 * (sh/4) x (W/32), band 9 is (sh/2) x (W/2), a factor of 128 in population --
 * so lifting the deadzone on the level-1 bands spends almost the whole cost of
 * the change, while the coarse bands carry the large-scale colour gradients a
 * viewer reads as "the colour went flat" and cost almost nothing.  9 = lift
 * everywhere (the unbounded form).  ledger sect.54.4 sweeps it. */
int omc_dz_plane = 7;
int omc_dz_cto = 9;
/* The per-plane deadzone predicate.  Kept as one function so that the ACTUAL
 * quantisation site and the three encoder-side VERIFICATION sites that must
 * predict it can never drift apart -- if they do, the encoder emits a stream
 * whose own verifier rejects it. */
static inline int omc_dz_on(int p, int b)
{
    if ((omc_dz_plane >> p) & 1) return 1;   /* plane keeps the deadzone */
    return b > omc_dz_cto;                   /* lifted only up to OMC_DZ_CTO */
}
int omc_gr_mode = 0;  /* grain-replace classifier knob (env OMC_GR=1) */
int omc_gr_pthr = 0;  /* flat-class parent threshold override (env OMC_GR_PTHR) */
int omc_gr_qmax = 1;  /* flat-class kill depth |q| <= qmax (env OMC_GR_QMAX) */
int omc_gr_notemp = 0; /* diagnostic: skip temporal vote in flat class */
int omc_gr_carpet = 0; /* pct: band needs >= pct%% small nonzero coefs for flat class (env OMC_GR_CARPET) */
int omc_gr_softcap = 3; /* soft-threshold only |q| <= cap (env OMC_GR_SOFTCAP) */
int omc_gr_llthr = 24; /* flat-class LL-gradient threshold (env OMC_GR_LLTHR) */
int omc_gr_soft = 0;   /* flat-class soft-threshold: coded |q| shrinks by n (env OMC_GR_SOFT) */
extern long long omc_fc_fire, omc_fc_tot;
int omc_fillgain_max = 3; /* sect.56: fill amplitude ceiling (env OMC_FILLGAIN_MAX) */
int omc_fillrows = 0;     /* sect.57: fill only the last N rows of each band (env OMC_FILLROWS) */
int omc_fillthr = 3;      /* sect.61: fill-bit threshold, sixteenths of a step (env OMC_FILLTHR) */
int omc_fillthr_c = -1;   /* sect.67: chroma fill-bit threshold (env OMC_FILLTHR_C); <0 = follow omc_fillthr */
/* sect.67: FILLTHR=0 drives CHROMA flatness to 0.00%% on every clip but breaks A4
 * on cf_gfx (sect.67.9).  A per-plane threshold lets the chroma planes take the
 * low threshold that fixes their flatness while luma keeps the value the lattice
 * argument needs.  Used by BOTH the live rule and lock_verify()'s mirror, so the
 * two cannot disagree. */
static inline int64_t omc_fillthr_p(int p)
{
    return (int64_t)((p != 0 && omc_fillthr_c >= 0) ? omc_fillthr_c : omc_fillthr);
}
/* sect.B1(v5.3.5): the rung-keyed CHROMA offer threshold.  At rung >= 1 the
 * mid-rate chroma flatness lives in bands whose mean eligible magnitude sits
 * BELOW 3/16 of a step but above zero (measured: threshold 1/16 fixes nothing,
 * 0 fixes it completely -- cityalley@1.0 Cb 31.9->0.00, bosphorus@1.0 Cb
 * 11.3->0.00 -- at unchanged NEG and zero blotch).  ENCODER-ONLY: the offer
 * lands in the transmitted fill_mask, the amplitude (and so the decoder) is
 * untouched, which is what keeps this shape clear of the sect.67.11 global
 * FILLTHR=0 A4 falsification -- that one moved AMPLITUDE-bearing offers; this
 * one is rung-gated, chroma-only, and A4 is re-proven by the v5.3.5 chain
 * battery.  An explicit OMC_FILLTHR_C still wins (A/B lever).  Declared int
 * forward: omc_fillrung_cur is defined further down. */
extern int omc_fillrung_cur;
extern int omc_fillcrung_cur;
static inline int64_t omc_fillthr_pr(int p)
{
    if (p != 0 && omc_fillthr_c < 0 && omc_fillcrung_cur >= 1) return 0;
    return omc_fillthr_p(p);
}

int omc_fillintra = 0;    /* sect.62: fill INTRA bands only; inter carries it forward (env OMC_FILLINTRA) */
int omc_antsgate = 0;     /* sect.63: LL-activity floor for the fill (env OMC_ANTSGATE); set in init */
int omc_antsavg = 0;      /* sect.63b: average the fill gate's activity over the LL 3x3 (env OMC_ANTSAVG) */

/* ---- sect.78.10: RAIL-AWARE FILL (env OMC_FILLRAIL / OMC_FILLREACH, 10-bit codes).
 * The fill does not draw the G7 wash -- it MANUFACTURES WORK FOR THE REPAIR.  A
 * block already against a container rail has no headroom, so a quarter-step of
 * synthetic grain there pushes committed samples out of legal range, and when
 * the gentle rule cannot clear the slice the repair falls back to the harsh
 * uncapped 3/4 cut of an LL coefficient -- whose DC gain to pixels is exactly 1,
 * so the cut becomes a visible level shift over the 4x32 LL support block.
 * FILLRAIL tightens the clip-headroom guard on the block's LL DC.  FILLREACH
 * asks the better question: |c0| + (gh+gv)/2 estimates the block's peak pixel
 * excursion from mid-grey, so refuse the fill when that reaches within N codes
 * of a rail.  Both key on the COMMITTED LL at the co-located cell -- the same
 * quantity the shipped clip-headroom guard already uses -- so both are
 * generation-invariant.  A refused position reconstructs to exactly zero, a
 * lattice point at every shift, so the candidate search is untouched. */
/* ---- sect.55.7: CANDIDATE K -- the chroma lifting divisor (env OMC_XSL_CDIV).
 * The clamp is not the limiter (8x the clamp moves the chroma seam <1%); the
 * /4 is.  Chroma's join is 3.5x its interior where luma's is 1.4x, so a quarter
 * is enough for luma and is not enough for chroma.  K halves the divisor for
 * the CHROMA planes only.  Invertibility untouched (rows 1 and 14 are never
 * read by either step); the divisor comes from the PLANE INDEX alone, so
 * nothing is signalled and it is generation-invariant.
 * F-4: this TRUNCATES TOWARD ZERO and is NOT an arithmetic shift -- the operand
 * is a signed difference, and >> 1 floors, differing on 23.3% of samples. */
/* ---- CANDIDATE L (env OMC_XSL_LOOPFREE, default 0 = shipped behaviour).
 * 1 = the interior boundary edit becomes DISPLAY-ONLY: the emitted picture
 * still gets the identical two-step lifting cascade -- applied in
 * xsl_display_blend instead of in reconstruct_slice -- but the committed
 * REFERENCE never sees it, so a boundary row is never re-edited from its own
 * already-edited value on the next frame.  The codec already does exactly this
 * at refresh barriers ("reference (d->ref) never sees it"); L extends that
 * scope.  Frame 0 is bit-identical; from frame 1 the reference and hence inter
 * prediction differ, so this is a NORMATIVE reconstruction change needing a
 * minor bump -- free under the owner's standing ruling.
 * Measured on the four 1080p arms at 0.5 bpp: luma slice-pitch periodicity
 * cityalley 0.2136 -> 0.1173 (-45%), readysetgo 0.1248 -> 0.0926 (-26%),
 * bosphorus 0.0732 -> 0.0507 (-31%), dng 0.0829 -> 0.0785; VMAF-NEG moves
 * +0.023 / +0.010 / -0.017 / -0.121, and dng's G7 blotch tail IMPROVES
 * (n>40 11 -> 6).  It also cuts the error-propagation loop gain inside the
 * refresh window from +6.6..+9.3 %/frame to +0.0..+2.1 %/frame, which is the
 * precondition for ever widening R.
 * The 0.969 NEG graphics loss recorded against L was measured on the
 * cf_gfx_448x256 proxy and does NOT reproduce on the real 1080p graphics arm,
 * where the cost is 0.121. */
int omc_xsl_loopfree = 0;
int omc_xsl_cdiv = 0;
static inline int32_t xsl_div_p(int32_t v, int p)
{
    return (omc_xsl_cdiv && p != 0) ? v / 2 : v / 4;
}
/* ---- sect.55.7: F-14 -- the boundary edit is DEAD at 8 bit.
 * lim = xsl_lim * ((maxv + 1) >> 10) evaluates 256 >> 10 == 0, so the clamp is
 * ZERO below 10 bits and the edit does nothing at all.  Repaired by scaling on
 * the true ratio with rounding and a floor of one code: reproduces the shipped
 * value EXACTLY at 10 bit (8) and 12 bit (32), and gives 2 instead of 0 at 8. */
int omc_xsl_depthfix = 0;
/* ---- sect.55.8: SPREAD THE BOUNDARY EDIT (env OMC_XSL_SPREAD), eighths of the
 * edit moved to the NEXT row in.  sect.55.7 closed on exactly this experiment
 * and left it unbuilt: "a cascade that also writes rows 1 and 14, so the
 * correction is spread symmetrically instead of dumped into the two rows
 * adjacent to untouched ones -- attack the relocation, not the attenuation."
 * SHIPPED DEFAULT 2.  Measured at an identical byte count, pitch.py Y/Cb/Cr:
 *   dng        0.0968/0.1132/0.1003 -> 0.0759/0.0798/0.0661   (-22/-29/-34%)
 *   cityalley  0.1195/0.0982/0.0914 -> 0.0868/0.0961/0.0888
 *   bosphorus  0.0483/0.1095/0.0990 -> 0.0399/0.0990/0.0904
 * dng blotch >40 also falls 6 -> 5.
 *
 * *** FALSIFIED AS BUILT.  DEFAULT 0.  DO NOT SHIP THIS FORM. ***
 * It BREAKS A4: gates G-T5-XSL2 and G-T5-XSL3a fail and 8 of 12 generation
 * chains fail pixels-gen2 (every sh=16 cell; sh=8 passes only because the
 * spread stands down there, and 8-bit passes only because xsl_lim_depth()
 * truncates the whole edit to zero below 10 bits -- the F-14 bug).
 *
 * The reason is in docs/XSL.md's own statement of the invariant: "A lifting
 * step is invertible when its correction depends only on values it does not
 * touch ... Rows 14 and 1 are NEVER TOUCHED by either."  Writing rows 14 and 1
 * is exactly what destroys that.  Step 1's correction reads row14; if step 1
 * also writes row14, the inverse can no longer recover the original and the
 * un-blend stops being the blend's inverse.  Generation exactness rests on that
 * pair being exact inverses (docs/TEMPORAL_T5.md: "the reversible boundary edit
 * + mandatory un-blend" is one of the three pillars).
 *
 * The IDEA is not falsified -- only this implementation of it.  sect.55.7 asked
 * for "a CASCADE that also writes rows 1 and 14", and a four-row cascade IS
 * constructible: lift the OUTER rows first, then the inner ones, so that each
 * step's correction still reads only rows that step does not write and the
 * inverse can undo them in reverse order.  See OMC_XSL_CASC (sect.55.8c). */
int omc_xsl_spread = 0;
/* ---- sect.55.8c: THE FOUR-ROW REVERSIBLE CASCADE (env OMC_XSL_CASC).
 *
 * sect.55.7 asked for "a CASCADE that also writes rows 1 and 14".  OMC_XSL_SPREAD
 * above tried to get there by SPLITTING one step's output across two rows, and
 * that is not invertible: step C's correction reads row14, so a step that also
 * writes row14 destroys the lifting property docs/XSL.md states as the
 * invariant.  Measured: A4 fails 8 of 12 cells and gates G-T5-XSL2/XSL3a fail.
 *
 * A cascade IS invertible if the OUTER rows are lifted FIRST, because then the
 * inverse can undo the steps in reverse order and each one still reads only
 * rows already restored or never touched:
 *
 *   forward   A: row14 += clamp(div(row15 - row13) >> casc, +-lim)
 *             B: row1  += clamp(div(row0  - row2 ) >> casc, +-lim)
 *             C: row15 += clamp(div(row0  - row14'),        +-lim)   <- as shipped
 *             D: row0  += clamp(div(row15'- row1' ),        +-lim)   <- as shipped
 *
 *   inverse   D': row0  -= ...(row15', row1')     both still present -> row0 back
 *             C': row15 -= ...(row0,   row14')    row0 restored      -> row15 back
 *             B': row1  -= ...(row0,   row2 )     row0 restored      -> row1 back
 *             A': row14 -= ...(row15,  row13)     row15 restored     -> row14 back
 *
 * Rows 13 and 2 are read and never written by any boundary, at any slice
 * height >= 8 (B4's shipping floor), so the cascade does not couple boundaries.
 * C and D are bit-for-bit the shipped arithmetic; casc = 0 is a no-op.
 * NORMATIVE -- both ends run it, so it needs the stream minor bumped. */
int omc_xsl_casc = 0;
static inline int32_t xsl_lim_depth(int32_t xsl_lim, int32_t maxv)
{
    if (!omc_xsl_depthfix) return xsl_lim * ((maxv + 1) >> 10);
    int32_t l = (int32_t)(((int64_t)xsl_lim * (maxv + 1) + 512) / 1024);
    return l < 1 ? 1 : l;
}
int omc_fillrail = 0;
int omc_fillreach = 0;
int omc_mvreg = 0;   /* [S5-MVREG] env OMC_MVREG: one motion vector per region */
int omc_mvreg_margin = 2;   /* [S5-MVREG] S5.19 global-vector fallback margin, sixteenths (env OMC_MVREG_MARGIN) */
/* [A1-MVBLK] BLOCK-LEVEL derived motion vectors (MEMO 001).  Declared here with the
 * other motion levers; read in omc_global_init_once() by BOTH ends (the derivation
 * runs in the encoder and, for design A, in the decoder as well). */
/* [A1-BLKHP] BLOCK-LAYER HALF-PEL (MEMO 017 5.1).  My eligibility funnel showed the
 * region-layer half-pel cannot act on high-motion content -- the [A1-MZ] model-fit floor
 * suppresses 91 % of regions on soccer2 and 0 of 236 eligible regions gain -- while the
 * block field, which does carry the motion, is integer-only because block half-pel was
 * reachable only through omc_mvhp >= 2, a value the decoder's conformance freeze pins out.
 * This makes the fraction reachable at the block layer.  NORMATIVE: it changes the unit of
 * the transmitted block delta from integer-pel to half-pel, so encoder and decoder must
 * agree and the freeze list must pin it.  Temporary lever, default 0, so byte-identity at
 * off can be gated; retired in favour of unconditional behaviour if the data supports it. */
int omc_blkhp = 0;

int omc_mvblk = 1;          /* env OMC_MVBLK: 0 = off (per-region vectors only, the A/B switch-off);
                             * 1 = ON with the normative width rule (picture width / 30, rounded to a
                             * multiple of 8, clamped [32,128] -- MEMO 004 item 5); > 1 = ON with that
                             * fixed width, for A/B probes only. */
int omc_mvblk_margin = 2;   /* env OMC_MVBLK_MARGIN: sixteenths a block's own SAD must beat its region's by */
int omc_mvblk_cstep = 2;    /* env OMC_MVBLK_CSTEP: column sampling stride of the block SAD */
int omc_mvblk_ob = 8;       /* env OMC_MVBLK_OB: overlapped-prediction half-width T in LUMA px (0/1/2/4/8).
                             * DEFAULT 8: without it a per-block vector field steps at every block
                             * edge and graphics and 8-bit lose 0.22 / 0.13 NEG; with it every gamut
                             * cell is inside the 0.1 bar and the motion cells gain more as well. */
int omc_mvblk_rdo = 2;      /* [A1-MVSIG] 0 = off, 1 = decide against the SOURCE (NOT generation-exact,
                             * documentation only), 2 = decide against COMMITTED history (default).
                             * Encoder-only, no wire effect: before coding a slice,
                             * compare the LUMA residual the block vectors produce against the one
                             * the region vectors produce, in the COEFFICIENT domain (which is what
                             * costs bits), and keep the block vectors only if they win.  Cures the
                             * cells where the block vectors find a better SAD but a worse residual
                             * (graphics, 8-bit).  Costs one extra luma prediction+transform/slice. */
int omc_mvblk_rdom = 16;     /* [A1-MVSIG] margin, in 256ths, that the block vectors' residual must
                             * beat the region vectors' by before the field is sent -- the field's
                             * own bit cost, charged against the residual it saves. */
long long omc_mvrdo_kept = 0, omc_mvrdo_drop = 0;
int omc_mvhp_bar = 0;       /* [A1-MVHPB] A5 REFRESH BARRIER for the motion fetch.  v4.9 already
                             * carries refresh barriers so "a refreshed slice's coding loop stays
                             * independent" (README) -- but that rule covers the vertical lifting's
                             * boundary term, not the prediction fetch, and the fetch is the path
                             * section 17.7 measured.  With this on, a fractional VERTICAL pair that
                             * would straddle a slice boundary drops its fraction for that row, so
                             * the error a lost slice injects can still be TRANSPORTED across bands
                             * (as integer motion does, harmlessly) but can no longer be DUPLICATED
                             * across them.  Derived from slice geometry on both sides; no new
                             * signalling.  Normative: encoder and decoder must agree. */
int omc_mvhp_mz   = 0;      /* [A1-MZ] MODEL-BENEFIT test, in 16ths -- the expert's replacement for
                             * raw vector dispersion.  Dispersion asks "do the region vectors
                             * disagree?"; it fires on any field that varies, including a perfectly
                             * coherent one.  Measured false positive: a dashcam (forward camera
                             * motion) has an EXPANDING field -- left and right regions move in
                             * opposite directions on 71.9 % of slices -- so dispersion fires on
                             * 42.7 % of its slices and suppresses half-pel that was helping,
                             * costing 0.27 NEG.
                             * The right question is whether a FINER model actually predicts better:
                             *     M = D(region translation) - D(piecewise translation)
                             * normalised by the innovation scale and sqrt(N_eff).  A dashcam's
                             * field varies smoothly, so per-half vectors barely beat the region
                             * vector and M stays small; genuine parallax has two motion layers in
                             * one region, so halves beat the whole decisively.
                             * Committed history only; the halves are searched locally around the
                             * region vector, so the extra cost is bounded. */
int omc_mvhp_gain = 0;      /* [A1-MVHPG] absolute floor on the half-pel SAD win, in 1/16 of a
                             * 10-bit code per sampled pixel (env OMC_MVHP_GAIN). */
int omc_mvhp = 0;           /* [A1-MVHP] env OMC_MVHP: allow HALF-PEL motion vectors.  The header field
                             * is already in half-pel units and both predict_plane() and the concealment
                             * path already implement the bilinear taps for odd codes -- T5 simply never
                             * emitted them ("low-pass re-filters, quality risk with zero exactness
                             * benefit").  The exactness half of that is right and unaffected: the
                             * refinement reads only committed history.  The quality half is measurable,
                             * and the §9 worth-it gate makes adopting it safe -- a slice pays for the
                             * finer field only where the finer field wins.
                             * 1 = half-pel region vectors (ENCODER-ONLY: no wire change, no decoder
                             *     change -- an existing decoder reads the odd codes correctly).
                             * 2 = also half-pel block vectors (the signalled deltas become half-pel
                             *     units, which is a wire-semantics change). */
int omc_mvblk_sig = 1;      /* [A1-MVSIG] MEMO 004 design (B): the block vectors are WRITTEN into
                             * the slice payload and the decoder reads them.  Default on.  0 falls
                             * back to design (A) (decoder derives), kept only as the A/B probe. */
/* [A1-OBEDGE] DELETED 2026-09-05 (MEMO 007 §5.1b). The edge veto on the overlapped blend was
 * encoder AND decoder code in the prediction path controlled by an environment variable --
 * the disagreement channel omc1.h:303-308 forbids -- and it measured worse on the v5.3.5 base
 * (it CAUSED both breaches of the owner's 0.1 NEG bar). Removed rather than disabled, at the
 * IP review's direction. Git history keeps the probe. */
int omc_mvblk_iso = 0;      /* [A1-ISO] SUPPORT-WEIGHTED block gate (expert round 6).
                             * The existing OMC_MVBLK_VAR gate is a blanket veto: a block with no
                             * agreeing neighbour keeps the region vector whatever its gain.  The
                             * expert's objection is that an isolated moving person LEGITIMATELY
                             * disagrees with the static floor around it -- the very case the field
                             * exists to carry -- so a veto throws away the good with the bad.
                             * The graded form instead RAISES the bar for an unsupported block:
                             *     required margin = omc_mvblk_margin + (support ? 0 : omc_mvblk_iso)
                             * in sixteenths.  A block in a coherent moving area keeps the ordinary
                             * threshold; an isolated block must clear a much larger one, because it
                             * is the isolated block that creates a predictor discontinuity at its
                             * edges, and that step lands in the wavelet detail bands where fixed CBR
                             * has to pay for it.  Diagnosis for VolleyballGame, where the field is
                             * used on 0.8 % of blocks and still costs 0.21-0.27 NEG.
                             * Neighbour-independent (uses the pass-1 raw vectors), so both ends
                             * would compute it identically and every block still parallelises. */
int omc_mvblk_varfire = 0;  /* counters for the gate's firing rate (diagnostic) */
static int32_t omc_fg_mid = 0;
static inline int32_t omc_lllim_of(int32_t mid)
{
    omc_fg_mid = mid;
    int32_t lim = mid - (mid >> 4);
    if (omc_fillrail > 0) {
        int32_t m = (int32_t)(((int64_t)omc_fillrail * mid) >> 9);
        int32_t l2 = mid - m;
        if (l2 < lim) lim = l2;
        if (lim < 0) lim = 0;
    }
    return lim;
}
/* ---- sect.64: TRUE HYSTERESIS ON THE FILL GATE (env OMC_ANTSHYST, in 1/16).
 *
 * Raising the gate (sect.63) stops the crawl by refusing fill to every marginal
 * position, which also refuses it to the genuinely flat ones the fill exists to
 * serve.  Hysteresis separates the two: a position needs the FULL threshold to
 * turn the fill ON, but only OMC_ANTSHYST/16 of it to STAY on.  Positions well
 * inside either state never flicker; only a genuine change in the picture moves
 * one across.
 *
 * "Stay on" is evaluated against the PREVIOUS frame's LL, which is exactly the
 * prediction's LL band -- `pcoef[p][0]` -- and which the encoder and the decoder
 * both hold before either touches a fill.  So the rule costs no syntax, and the
 * two ends derive it from the same integers.
 *
 * It is armed per band and ONLY on inter bands: on an intra band there is no
 * prediction and `pcoef` holds nothing meaningful, so the pointer is left null
 * and the gate falls back to the plain threshold. */
const int32_t *omc_pll = 0;   /* previous frame's LL for this band, or null */
int omc_pllw = 0;             /* its stride */
int omc_antshyst = 0;         /* 0 = off; else the stay-on fraction, in 1/16 */
int omc_fillstat = 0;         /* sect.65: count applied fills (env OMC_FILLSTAT) */
int omc_fillamp = 0;          /* sect.66 DIAGNOSTIC: pin the fill amplitude (env OMC_FILLAMP) */
/* [LEGACY-REPAIR] lever */
int omc_gm_keepfill = 0;  /* sect.67: do not let the gamut repair veto fill (env OMC_GM_KEEPFILL) */
/* ---- sect.78.10: THE FILL VETO AS AN ESCALATION RUNG (env OMC_GM_VETOAT).
 * v5.2 vetoes a band's grain fill the MOMENT the in-gamut repair touches it,
 * which is why a louder fill produced MORE flatness.  1 = arm the veto only
 * once the slice restarts on the harsh rule; 2 = try it as its own rung, after
 * the bounded ladder and BEFORE the unbounded redo; 3 = never (== KEEPFILL).
 * Encoder-side search order only -- the fill mask is transmitted in the slice
 * header, so no decoder and no lock_verify mirror changes. */
/* [LEGACY-REPAIR] lever */
int omc_gm_vetoat = 0;
int omc_fillmin1 = 0;   /* sect.67.12: admit amplitude 1 (env OMC_FILLMIN1) */
int omc_fillelig_c = 0; /* v5.3.5 B1 PROBE: drop the partial-chunk +1 from the CHROMA
                         * band-offer eligibility precheck, admitting base_s ==
                         * MIN_SHIFT+div bands (amplitude still >= 2 codes; the
                         * partial chunk is refused by fill_value_p's sh_<1 guard
                         * on both sides symmetrically). Encoder-only: the offer
                         * lands in the transmitted fill_mask. (env OMC_FILLELIG_C) */
int omc_diveff = 0;   /* sect.67: per-band effective fill divisor (env OMC_DIVEFF) */
int omc_filldiv = 0;          /* sect.66b: halvings of the fill amplitude (env OMC_FILLDIV) */
int omc_filldiv_c = -1;  /* sect.67.13: chroma fill divisor (env OMC_FILLDIV_C); <0 = follow omc_filldiv */
/* sect.67.13: the divisor must be keyed on a quantity that CANNOT change between
 * generations.  The shift s can (the calm kill moves it) -- that is why OMC_DIVEFF
 * broke G-T5-CALM2a/2b.  The PLANE INDEX cannot.  A per-plane divisor therefore
 * keeps the amplitude linear in s within each plane, leaving the gain fixed point
 * of sect.62 intact, while letting the chroma planes reach the base_s 4-5 bands
 * where their flatness lives. */
/* sect.B1(v5.3.5): master switch for the fill divisor's rate rung (see the
 * ctx_common_t field).  1 = rung derived from the stream (v5.3.5 default);
 * 0 = rung pinned to 0, which reproduces the v5.3 fill exactly (A/B arm).
 * NORMATIVE: the decoder computes the same rung from the same header fields,
 * so this lever is pinned in the decoder by the conformance freeze once
 * default-on. */
int omc_fillrung = 1;
/* the CURRENT context's rung, set at the top of the encoder's and decoder's
 * slice paths from ctx_common_t.fill_rung (the same set-before-use pattern
 * omc_pll/omc_pllw already use in this file).  Everything the fill derives --
 * amplitude, gain fold, band offer, lattice admission -- reads the divisor
 * through omc_filldiv_pr() below so all sites move together; the sect.62
 * failure was exactly two of these sites disagreeing. */
int omc_fillrung_cur = 0;
int omc_fillcrung_cur = 0;   /* sect.B5: chroma-lever rung, set beside fillrung_cur */
static inline int omc_filldiv_p(int pl)
{
    return (pl != 0 && omc_filldiv_c >= 0) ? omc_filldiv_c : omc_filldiv;
}
/* the EFFECTIVE divisor under the rate rung (sect.B1, minor 14):
 *   luma:   d0 - 1 at rung >= 1 (0.375 b/cs and up), only while d0 > 1 --
 *           so the v5.0 restore's FILLDIV=0 stays 0 and luma never reaches
 *           the full step (full-step luma is the sect.78.10 falsification,
 *           reproduced here as 6 residual oob on G-T5-CUT4's plates);
 *   chroma: 0 (full step) at rung 2 (>= 0.75 b/cs).
 * NEITHER IS SAFE WITHOUT THE RUNG-2 REACH GUARD in fill_gate_g.  The bare
 * amplitude raises were all measured and falsified first: luma div 1 at 2.0
 * bpp gave blotch worst -141 / n>40 93 / NEG -2.4 (sun-glint clip damage,
 * local errors to -402 codes), chroma div 0 at 1.0 bpp gave luma n>20
 * 118..191 / NEG -2.6.  With the guard refusing fill where the block's peak
 * excursion reaches within 64 codes of a rail, the same amplitudes measure
 * BLOTCH-CLEAN (n>20 0) at unchanged NEG, and close the flatness class:
 * bosphorus@2.0 Cb 16.9 -> 0.00, cityalley@2.0 Cb 9.0 -> 0.00, luma
 * 2.66 -> 1.6 / 5.43 -> 2.8.  At rung 1 the measured return is cityalley@1.0
 * luma 9.18 -> 0.00 and bosphorus@1.0 6.33 -> 0.30 for -0.07..+0.05 NEG.
 * The keys (plane, rung) are both generation-invariant. */
static inline int omc_filldiv_pr(int pl)
{
    int d0 = omc_filldiv_p(pl);
    if (pl == 0 && omc_fillrung_cur >= 1 && d0 > 1) return d0 - 1;
    if (pl != 0 && omc_fillrung_cur >= 2) return 0;
    return d0;
}
/* sect.67: OMC_FILLDIV=2 makes the fill amplitude 1<<(s-2-2), which rounds away
 * for s < 5, so the band-offer test refuses every band with base_s < 6 and those
 * bands are left with NO fill at all.  Measured: that is where the residual luma
 * flatness lives.  The effective divisor is the LARGEST divisor that still yields
 * an amplitude of at least 2, so a coarse band keeps the quiet 1/16-step fill and
 * a finer band fills at the quietest amplitude it can represent instead of being
 * skipped.  It is a PURE FUNCTION OF s, so the amplitude site, the band-offer
 * test and the lattice admission window all derive the same value independently
 * and cannot drift apart -- that asymmetry is what broke A4 at 720p before. */
static inline int omc_div_eff_of(int s)
{
    int d = omc_filldiv;
    if (d > s - 3) d = s - 3;
    if (d < 0) d = 0;
    return d;
}
/* can a band whose coefficients carry shift s produce a legal fill amplitude? */
static inline int omc_fill_sh_ok(int s)
{
    return s >= OMC_FILL_MIN_SHIFT && (s - 2 - omc_div_eff_of(s)) >= 1;
}
int64_t omc_fill_hits = 0;
int64_t omc_fill_slots = 0;

/* ---- OMC_FDBG: READ-ONLY instrumentation (partial-chunk / sh_ study).
 * Every counter below is written only when omc_fdbg is nonzero and is never
 * read by any coding decision.  Remove with the block markers FDBG-BEGIN/END. */
/* FDBG-BEGIN */
int omc_fdbg = 0;
int64_t fdbg_refuse_sh[32];    /* fill refused by the sh_ >= 1 test, by s */
int64_t fdbg_fill_ok[32];      /* fill produced, by s */
int64_t fdbg_refuse_min[32];   /* fill refused by s < OMC_FILL_MIN_SHIFT, by s */
int64_t fdbg_part_fillband;    /* derive_shifts put partial chunks in a fill band */
int64_t fdbg_part_any;         /* derive_shifts produced partial chunks at all */
int64_t fdbg_split_band;       /* fill band whose positions span two shifts */
int64_t fdbg_split_mixed;      /* ... and the two shifts straddle the sh_ test */
static void fdbg_dump(void)
{
    fprintf(stderr, "FDBG filldiv=%d part_any=%lld part_fillband=%lld "
            "split_band=%lld split_mixed=%lld\n", omc_filldiv,
            (long long)fdbg_part_any, (long long)fdbg_part_fillband,
            (long long)fdbg_split_band, (long long)fdbg_split_mixed);
    for (int s = 0; s < 32; s++)
        if (fdbg_refuse_sh[s] | fdbg_fill_ok[s] | fdbg_refuse_min[s])
            fprintf(stderr, "FDBG  s=%2d fill=%lld refused_sh=%lld refused_min=%lld\n",
                    s, (long long)fdbg_fill_ok[s], (long long)fdbg_refuse_sh[s],
                    (long long)fdbg_refuse_min[s]);
}
/* FDBG-END */
