int omc_fillhystr_c = 3;  /* sect.61: hysteresis relaxed threshold, chroma, /32 (env OMC_FILLHYSTR_C) */
int omc_fillhystr_y = 4;  /* sect.61: hysteresis relaxed threshold, luma,  /32 (env OMC_FILLHYSTR_Y) */
