    omc_dz_cto = getenv("OMC_DZ_CTO") ? atoi(getenv("OMC_DZ_CTO")) : 9;
    omc_gr_mode = getenv("OMC_GR") ? atoi(getenv("OMC_GR")) : 0;
    omc_gr_pthr = getenv("OMC_GR_PTHR") ? atoi(getenv("OMC_GR_PTHR")) : 0;
    omc_gr_qmax = getenv("OMC_GR_QMAX") ? atoi(getenv("OMC_GR_QMAX")) : 1;
    omc_gr_notemp = getenv("OMC_GR_NOTEMP") ? atoi(getenv("OMC_GR_NOTEMP")) : 0;
    omc_gr_fillveto = getenv("OMC_GR_FILLVETO") ? atoi(getenv("OMC_GR_FILLVETO")) : 0;
    omc_calm = getenv("OMC_CALM") ? (atoi(getenv("OMC_CALM")) != 0) : 1;
    omc_calm_thr = getenv("OMC_CALM_THR") ? atoi(getenv("OMC_CALM_THR")) : 24;
    omc_calm_amp = getenv("OMC_CALM_AMP") ? atoi(getenv("OMC_CALM_AMP")) : 3;
    /* [LEGACY-REPAIR] lever read */
    omc_gm_dil = getenv("OMC_GM_DIL") ? atoi(getenv("OMC_GM_DIL")) : 1;
    /* [LEGACY-REPAIR] lever read */
    omc_gm_dilfrom = getenv("OMC_GM_DILFROM") ? atoi(getenv("OMC_GM_DILFROM")) : 2;
    /* [LEGACY-REPAIR] lever read */
    omc_gm_llhold = getenv("OMC_GM_LLHOLD") ? atoi(getenv("OMC_GM_LLHOLD")) : 0;
    /* [LEGACY-REPAIR] lever read */
    omc_gm_bandhold = getenv("OMC_GM_BANDHOLD") ? atoi(getenv("OMC_GM_BANDHOLD")) : 0;
    /* [LEGACY-REPAIR] lever read */
    omc_gm_llcap = getenv("OMC_GM_LLCAP") ? atoi(getenv("OMC_GM_LLCAP")) : -2;
    /* [LEGACY-REPAIR] lever read */
    omc_gm_llcapsh = getenv("OMC_GM_LLCAPSH") ? atoi(getenv("OMC_GM_LLCAPSH")) : 0;
    omc_chunkstat = getenv("OMC_CHUNKSTAT") ? atoi(getenv("OMC_CHUNKSTAT")) : 0;
    {
        static int q5reg = 0;
        omc_q5stat = getenv("OMC_Q5STAT") ? atoi(getenv("OMC_Q5STAT")) : 0;
        omc_q5live = getenv("OMC_Q5LIVE") ? atoi(getenv("OMC_Q5LIVE")) : 0;
        omc_q5flag = getenv("OMC_Q5FLAG") ? atoi(getenv("OMC_Q5FLAG")) : 16;   /* sect.80: Q5 ON by default */
        omc_q5measure = getenv("OMC_Q5MEASURE") ? atoi(getenv("OMC_Q5MEASURE")) : 0;
        omc_q5greedy = getenv("OMC_Q5GREEDY") ? atoi(getenv("OMC_Q5GREEDY")) : 0;
        omc_q5intra = getenv("OMC_Q5INTRA") ? atoi(getenv("OMC_Q5INTRA")) : 1;
    omc_lock_tieact = getenv("OMC_LOCK_TIEACT") ? atoi(getenv("OMC_LOCK_TIEACT")) : 1;
        omc_q5share = getenv("OMC_Q5SHARE") ? atoi(getenv("OMC_Q5SHARE")) : 0;
        if (omc_q5measure && !q5reg) { q5reg = 1; atexit(q5_report); }
        if (omc_q5stat && !q5reg) { q5reg = 1; atexit(q5_report); }
        if (omc_q5live) { static int q5lreg; if (!q5lreg) { q5lreg = 1; atexit(q5live_report); } }
    }
    /* [LEGACY-REPAIR] lever read */
    omc_gm_llprop = getenv("OMC_GM_LLPROP") ? atoi(getenv("OMC_GM_LLPROP")) : 0;
    /* [LEGACY-REPAIR] lever read */
