    /* [LEGACY-REPAIR] lever read */
    omc_gm_llbnd = getenv("OMC_GM_LLBND") ? atoi(getenv("OMC_GM_LLBND")) : 2;
    /* [LEGACY-REPAIR] lever read */
    omc_gm_llreach = getenv("OMC_GM_LLREACH") ? atoi(getenv("OMC_GM_LLREACH")) : 0;
    /* [LEGACY-REPAIR] lever read */
    omc_gm_llgive = getenv("OMC_GM_LLGIVE") ? atoi(getenv("OMC_GM_LLGIVE")) : 0;
