    omc_gm_biteff = getenv("OMC_GM_BITEFF") ? atoi(getenv("OMC_GM_BITEFF")) : 0;
    /* [LEGACY-REPAIR] lever read */
    omc_gm_escmode = getenv("OMC_GM_ESCMODE") ? atoi(getenv("OMC_GM_ESCMODE")) : 2;
    /* [LEGACY-REPAIR] lever read */
